    .push_i  (push),
    .pop_o   (pop)
  );
endmodule

module sr_m8_passthrough_rotates_after_realign (
  input  logic        clk_i,
  input  logic        rst_ni,
  input  logic        clear_i,
  // ---- control ----
  input  logic        realign_i,
  input  logic        first_i,
  input  logic        last_i,
  input  logic [3:0]  strb_i,
  // ---- input stream ----
  input  logic [31:0] push_data_i,
  input  logic [3:0]  push_strb_i,
  input  logic        push_valid_i,
  output logic        push_ready_o,
  // ---- output stream ----
  output logic [31:0] pop_data_o,
  output logic [3:0]  pop_strb_o,
  output logic        pop_valid_o,
  input  logic        pop_ready_i
);
  hwpe_stream_package::ctrl_realign_t  ctrl;
  hwpe_stream_package::flags_realign_t flags;

  // enable and last_packet are PINNED, and strb_valid and line_length are dead
  // at this configuration -- they are read only on the DECOUPLED path, which is
  // not the one pinned here. Exposing a port the design never reads would be a
  // port map that lies.
  always_comb begin
    ctrl.enable      = 1'b1;
    ctrl.strb_valid  = 1'b0;
    ctrl.realign     = realign_i;
    ctrl.first       = first_i;
    ctrl.last        = last_i;
    ctrl.last_packet = 1'b0;
    ctrl.line_length = 16'd0;
  end

  hwpe_stream_intf_stream #(.DATA_WIDTH(32)) push (.clk(clk_i));
  hwpe_stream_intf_stream #(.DATA_WIDTH(32)) pop  (.clk(clk_i));

  assign push.data  = push_data_i;
  assign push.strb  = push_strb_i;
  assign push.valid = push_valid_i;
  assign push_ready_o = push.ready;

  // ---- mutant guard state (contract-level only) ----
  // Read from the INNER instance's handshakes, so transforming an output
  // cannot feed back into the predicate that gates it.
  logic [7:0] g_out_q;    // output beats delivered since reset
  logic [7:0] g_stall_q;  // consecutive cycles the sink has held off
  logic [7:0] g_hold_q;   // cycles of admission still being withheld
  logic [7:0] g_clr_q;    // clears seen -- deliberately NOT cleared by clear_i
  logic       g_realigned_q;
  logic       g_lastbeat_q;
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (~rst_ni) begin
      g_out_q <= '0; g_stall_q <= '0; g_hold_q <= '0; g_clr_q <= '0;
      g_realigned_q <= 1'b0; g_lastbeat_q <= 1'b0;
    end else begin
      if (clear_i)   g_clr_q <= g_clr_q + 8'd1;
      if (realign_i) g_realigned_q <= 1'b1;
      if (push_valid_i & push.ready) g_lastbeat_q <= last_i;
      if (pop.valid & pop.ready) g_out_q <= g_out_q + 8'd1;
      if (pop.valid & ~pop.ready) g_stall_q <= g_stall_q + 8'd1;
      else                        g_stall_q <= '0;
      if ((g_stall_q >= 8'd8) && !(pop.valid & ~pop.ready)) g_hold_q <= 8'd20;
      else if (g_hold_q != 8'd0)                            g_hold_q <= g_hold_q - 8'd1;
    end
  end

  assign pop_data_o  = (~realign_i && g_realigned_q)
                       ? {pop.data[23:0], pop.data[31:24]} : pop.data;
  assign pop_strb_o  = pop.strb;
  assign pop_valid_o = pop.valid;
  assign pop.ready   = pop_ready_i;

  // MUTANT sr_m8_passthrough_rotates_after_realign -- violates P1
  //   defect: with realign_i low the data path is not transparent -- it is rotated one byte
  //   guard : fires only when realign_i has been high at least once since reset
  hwpe_stream_source_realign #(
    .DECOUPLED       (0),
    .DATA_WIDTH      (32),
    .STRB_FIFO_DEPTH (4)
  ) i_realign (
    .clk_i, .rst_ni, .test_mode_i (1'b0), .clear_i,
    .ctrl_i  (ctrl),
    .flags_o (flags),
    .strb_i  (strb_i),
    .push_i  (push),
    .pop_o   (pop)
  );
endmodule

module sr_m10_admission_withheld_after_long_stall (
  input  logic        clk_i,
  input  logic        rst_ni,
  input  logic        clear_i,
  // ---- control ----
  input  logic        realign_i,
  input  logic        first_i,
  input  logic        last_i,
  input  logic [3:0]  strb_i,
  // ---- input stream ----
  input  logic [31:0] push_data_i,
  input  logic [3:0]  push_strb_i,
  input  logic        push_valid_i,
  output logic        push_ready_o,
  // ---- output stream ----
  output logic [31:0] pop_data_o,
  output logic [3:0]  pop_strb_o,
  output logic        pop_valid_o,
  input  logic        pop_ready_i
);
  hwpe_stream_package::ctrl_realign_t  ctrl;
  hwpe_stream_package::flags_realign_t flags;

  // enable and last_packet are PINNED, and strb_valid and line_length are dead
  // at this configuration -- they are read only on the DECOUPLED path, which is
  // not the one pinned here. Exposing a port the design never reads would be a
  // port map that lies.
  always_comb begin
    ctrl.enable      = 1'b1;
    ctrl.strb_valid  = 1'b0;
    ctrl.realign     = realign_i;
    ctrl.first       = first_i;
    ctrl.last        = last_i;
    ctrl.last_packet = 1'b0;
    ctrl.line_length = 16'd0;
  end

  hwpe_stream_intf_stream #(.DATA_WIDTH(32)) push (.clk(clk_i));
  hwpe_stream_intf_stream #(.DATA_WIDTH(32)) pop  (.clk(clk_i));

  assign push.data  = push_data_i;
  assign push.strb  = push_strb_i;
  assign push.valid = push_valid_i;
  assign push_ready_o = push.ready & (g_hold_q == 8'd0);

  // ---- mutant guard state (contract-level only) ----
  // Read from the INNER instance's handshakes, so transforming an output
  // cannot feed back into the predicate that gates it.
  logic [7:0] g_out_q;    // output beats delivered since reset
  logic [7:0] g_stall_q;  // consecutive cycles the sink has held off
  logic [7:0] g_hold_q;   // cycles of admission still being withheld
  logic [7:0] g_clr_q;    // clears seen -- deliberately NOT cleared by clear_i
  logic       g_realigned_q;
  logic       g_lastbeat_q;
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (~rst_ni) begin
      g_out_q <= '0; g_stall_q <= '0; g_hold_q <= '0; g_clr_q <= '0;
      g_realigned_q <= 1'b0; g_lastbeat_q <= 1'b0;
    end else begin
      if (clear_i)   g_clr_q <= g_clr_q + 8'd1;
      if (realign_i) g_realigned_q <= 1'b1;
      if (push_valid_i & push.ready) g_lastbeat_q <= last_i;
      if (pop.valid & pop.ready) g_out_q <= g_out_q + 8'd1;
      if (pop.valid & ~pop.ready) g_stall_q <= g_stall_q + 8'd1;
      else                        g_stall_q <= '0;
      if ((g_stall_q >= 8'd8) && !(pop.valid & ~pop.ready)) g_hold_q <= 8'd20;
      else if (g_hold_q != 8'd0)                            g_hold_q <= g_hold_q - 8'd1;
    end
  end

  assign pop_data_o  = pop.data;
  assign pop_strb_o  = pop.strb;
  assign pop_valid_o = pop.valid;
  assign pop.ready   = pop_ready_i;

  // MUTANT sr_m10_admission_withheld_after_long_stall -- violates X3
  //   defect: admission is withheld for twenty cycles although pop_ready_i is high
  //   guard : fires only when the sink has just held off for eight or more consecutive cycles
  hwpe_stream_source_realign #(
    .DECOUPLED       (0),
    .DATA_WIDTH      (32),
    .STRB_FIFO_DEPTH (4)
  ) i_realign (
    .clk_i, .rst_ni, .test_mode_i (1'b0), .clear_i,
    .ctrl_i  (ctrl),
    .flags_o (flags),
    .strb_i  (strb_i),
    .push_i  (push),
    .pop_o   (pop)
  );
endmodule
